-- Migration 20261030211330_corpus_segments: generated by drizzle-kit, partition DDL, lz4 and grants hand-written and reviewed before commit.
-- Reviewed-by: Claude (agent, #893)
-- Corpus segments (#893, ADR 0051): judgment_segment is a global table (no workspace_id, no RLS) of redacted passages with a role, page anchors, a generated lexical vector (GIN) and a nullable halfvec embedding. It is range-partitioned by judgment_year in decades with a default partition (drizzle does not model partitions, so the DDL is written by hand); the primary key and the unique index carry the partition key. lz4 compression is set on judgment_segment.text and on judgment.page_text and redacted_text. judgment gains segment_version and segmented_redaction_version. The app role may SELECT, INSERT and DELETE segments (the corpus.segment job replaces a judgment's segments) and UPDATE only the two segment columns of judgment. Additive only.
CREATE TABLE "judgment_segment" (
	"id" uuid DEFAULT gen_random_uuid() NOT NULL,
	"judgment_id" uuid NOT NULL,
	"ordinal" integer NOT NULL,
	"role" text NOT NULL,
	"page_from" integer NOT NULL,
	"page_to" integer NOT NULL,
	"text" text NOT NULL,
	"court" text NOT NULL,
	"court_level" text NOT NULL,
	"judgment_year" integer NOT NULL,
	"search_tsv" "tsvector" GENERATED ALWAYS AS (setweight(to_tsvector('english', "text"), 'A') || to_tsvector('simple', "text")) STORED,
	"embedding" halfvec(1024),
	CONSTRAINT "judgment_segment_id_judgment_year_pk" PRIMARY KEY("id","judgment_year"),
	CONSTRAINT "judgment_segment_role_check" CHECK ("judgment_segment"."role" in ('header','facts','issues','arguments','reasoning','decision','other')),
	CONSTRAINT "judgment_segment_pages_check" CHECK ("judgment_segment"."page_from" >= 1 and "judgment_segment"."page_to" >= "judgment_segment"."page_from")
) PARTITION BY RANGE ("judgment_year");
--> statement-breakpoint
CREATE TABLE "judgment_segment_pre1950" PARTITION OF "judgment_segment" FOR VALUES FROM (MINVALUE) TO (1950);--> statement-breakpoint
CREATE TABLE "judgment_segment_1950s" PARTITION OF "judgment_segment" FOR VALUES FROM (1950) TO (1960);--> statement-breakpoint
