CREATE TABLE "judgment_segment_1980s" PARTITION OF "judgment_segment" FOR VALUES FROM (1980) TO (1990);--> statement-breakpoint
CREATE TABLE "judgment_segment_1990s" PARTITION OF "judgment_segment" FOR VALUES FROM (1990) TO (2000);--> statement-breakpoint
CREATE TABLE "judgment_segment_2000s" PARTITION OF "judgment_segment" FOR VALUES FROM (2000) TO (2010);--> statement-breakpoint
CREATE TABLE "judgment_segment_2010s" PARTITION OF "judgment_segment" FOR VALUES FROM (2010) TO (2020);--> statement-breakpoint
CREATE TABLE "judgment_segment_2020s" PARTITION OF "judgment_segment" FOR VALUES FROM (2020) TO (2030);--> statement-breakpoint
CREATE TABLE "judgment_segment_2030s" PARTITION OF "judgment_segment" FOR VALUES FROM (2030) TO (2040);--> statement-breakpoint
CREATE TABLE "judgment_segment_default" PARTITION OF "judgment_segment" DEFAULT;--> statement-breakpoint
ALTER TABLE "judgment" ADD COLUMN "segment_version" integer DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE "judgment" ADD COLUMN "segmented_redaction_version" integer DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE "judgment_segment" ADD CONSTRAINT "judgment_segment_judgment_id_judgment_id_fk" FOREIGN KEY ("judgment_id") REFERENCES "public"."judgment"("id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
CREATE UNIQUE INDEX "judgment_segment_ordinal_uq" ON "judgment_segment" USING btree ("judgment_id","ordinal","judgment_year");--> statement-breakpoint
CREATE INDEX "judgment_segment_search_tsv_idx" ON "judgment_segment" USING gin ("search_tsv");--> statement-breakpoint
ALTER TABLE "judgment_segment" ALTER COLUMN "text" SET COMPRESSION lz4;--> statement-breakpoint
